{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is neutral or negative (sentiment <= 0.00) and model overestimates prices.",
    "Reduce forecast magnitude by 5-10% if recent history shows mean reversion toward lower prices (e.g., 3-5 consecutive days of declining prices).",
    "Increase forecast sensitivity to recent price spikes (last 3-5 days) if sentiment is positive (sentiment > 0.00) — avoid overshoot by capping upward revisions at +10% of recent high.",
    "Apply lag correction: if true outcome is significantly lower than forecast, delay upward adjustments by 1-2 days to avoid overreacting to short-term volatility.",
    "When sentiment shifts from neutral to positive, increase forecast volatility by 10% to reflect market anticipation — but cap at 20% above recent mean.",
    "For long-term horizons (>15 days), apply smoothing: reduce forecast variance by 20% if recent 5-day average is stable or trending downward."
  ]
}
